INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (1, N'झोपडपट्टी पुनर्वसन योजना म्हणजे काय?', N'झोपडपट्टी पुनर्वसन प्राधिकरणाच्या कार्य क्षेत्रातील म्हणजेच पुणे व पिंपरी चिंचवड महानगरपालिका क्षेत्रातील झोपडपट्टी, गलिच्छ वस्तीत वास्तव्य असणा-या पत्र झोपडीधारका कुटुंबास झोपडीच्या/घराच्या ऐवजी मोफत पक्की सदनिका मालकी हक्कने देण्याची ही योजना आहे. सदनिका ३०० चौ.फुट (२७.८८ चौ.मी.) चटई क्षेत्राची असेल व सदनिकेमध्ये एक बहुप्रयोगी खोली(हॉल), स्वयंपाकासाठी जागा व स्वतंत्र संडास व न्हाणीघर देण्यात येते.', N'What is a Slum Rehabilitation Scheme?', N'The plan is to give free pucca flats to the slum dwellers living in slums, slums within the jurisdiction of Slum Rehabilitation Authority i.e. Pune and Pimpri Chinchwad Municipal Corporation. The flat will have a floor area of ​​ 300 sq. Ft. (27.88 sq.m.) and the flat will have a multi-purpose room (hall), space for cooking and a separate toilet and bathroom.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-04-29T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (2, N'झोपडपट्टी पुनर्वसनाचे लाभ घेण्यास कोण पात्र ठरतो? किंवा झोपडपट्टी पुनर्वसनाचे लाभ कोणास मिळतात?', N'झोपडपट्टी पुनर्वसनासाठी प्रत्यक्षात झोपडीत राहात असणारा झोपडीवासीय पात्र ठरतो एखादी व्यक्ती सदर झोपडीची मालक म्हणून हक्क सांगत असली, परंतु ती प्रत्यक्ष सदर झोपडीत राहत नसेल तर ती पुनर्वसनाचे लाभ घेण्यास पात्र ठरत नाही.', N'Who is eligible to benefit from slum rehabilitation? Or who gets the benefits of slum rehabilitation?', N'A slum dweller who is actually living in a hut is eligible for slum rehabilitation. If a person is claiming to be the owner of the hut, but he is not actually living in the hut, then he is not eligible for rehabilitation benefits.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (3, N'दिनांक 01/01/2000 नंतर वास्तव्यास असलेल्या झोपडीवासीय पात्र ठरू शकतो का?', N'झोपडीची गणना होवून त्याचा फोटोपास असलेली झोपडी (संरक्षित झोपडी) झोपडीमध्ये प्रत्यक्ष राहत असलेल्या झोपडीवासीयाने विकत घेतलेली असेल तर तो झोपडपट्टी पुनर्वसन प्रधीकारणाकडून पुनवर्सनास पात्र ठरतो.', N'Can a slum dweller living after 01/01/2000 be eligible?', N'If the hut (protected hut) with its photo pass is purchased by the slum dweller actually living in the hut, it is eligible for rehabilitation from the Slum Rehabilitation Authority.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (4, N'झोपडीच्या मूळ मालकाने झोपडी विकली असल्यास तो मूळ मालक पुनर्वसनास पात्र ठरतो का?', N'असा मूळमालक पुनर्वसनास पात्र ठरत नाही. तसेच तो शासनाच्या इतर घरांच्या योजनांसाठी अपात्र ठरतो.', N'If the original owner of the hut sold the hut, is the original owner eligible for rehabilitation?', N'Such an original owner is not eligible for rehabilitation. It also disqualifies the government from other housing schemes.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (5, N'एखाद्या झोपडीधारकाचे नाव योजना क्षेत्रातील आवश्यक असणाऱ्या मतदार यादीमध्ये आहेत व त्याचे झोपडपट्टी विरहीत क्षेत्रातील आवश्यक असणाऱ्या मतदार यादी मध्ये देखील नाव असल्यास तो झोपडीधारक पात्र ठरतो का?', N'मूळमालक पुनर्वसनास पात्र ठरत नाही.', N'Does a hut holder become eligible if his / her name is in the required voter list in the planned area and also in the required voter list in non-slum area?', N'The original owner is not eligible for rehabilitation.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (6, N'डोंगरमाथा, डोंगरउतार, हरित करण्यातपट्टे ,नदी नाला पात्रे, मंजूर रेखांकनातील खुल्या जागा तसेच सार्वजनिकवापरासाठी आवश्यकजागा ई. जागावरील झोपड्याचे पुनर्वसन त्याच जागेवर केले जाते का?', N'नाही. सदर जागावरील पात्र झोपडीवासीयांचे पुनर्वसन प्राधिकरणाच्या इतर योजनेमध्ये येते.', N'Mountain tops, hill slopes, greening belts, river channel basins, open spaces in approved drawings as well as places required for public use e. Is the on-site hut rehabilitated on the same site?', N'No. Rehabilitation of eligible slum dwellers on this site comes under other schemes of the authority.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (7, N'परवानगी नसलेल्या वाणिज्य गोडावून/गायीचे गोठे, भंगार गोडावून सार्वजनिक हितास अपायकारक वापर असलेली बांधकामे यांना झोपडपट्टी पुनर्वसन प्रधीकारनाकडून पुनर्वसनास परवानगी मिळते का? त्याचे पुनर्वसन कोठे केले जाते?', N'झोपडपट्टी पुनर्वसन प्रधीकारनाकडून पुनर्वसनास परवानगी दिली जात नाही त्यांना पुनर्वसन क्षेत्रापासून हटविले जाते.', N'Does the Slum Rehabilitation Authority allow rehabilitation of unauthorized commercial godowns / cow sheds, scrap sheds and constructions which are harmful to the public interest? Where is he rehabilitated?', N'Rehabilitation is not permitted by the Slum Rehabilitation Authority They are removed from the rehabilitation area.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (8, N'झोपडीधारकाची व झोपडीची नोंद सरकार दप्तरी आहे किंवा कसे या बाबतची माहिती कोठून समजेल?', N'दिनांक 01/01/2000 रोजीच्या मतदार यादीत झोपडीधारकांचे नाव व झोपडीचा स्वतंत्र क्रमांक नमूद केलेला असतो. मतदार यादीच्या संबंधित भागाची संक्षांकित प्रत त्या मतदार संघाच्या मतदार नोंदणी अधिकाऱ्याकडे किंवा जिल्हाधिकारी तथा जिल्हा निवडणूक अधिकारी यांचेकडे मिळू शकते.', N'Is the record of hut owner and hut kept by the government or how can one know the information about this?', N'The names of the hut holders and the separate number of the hut are mentioned in the voter list dated 01/01/2000. An abbreviated copy of the relevant part of the voter list can be obtained from the Voter Registration Officer of that constituency or from the Collector and District Election Officer.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (9, N'झोपडपट्टी पुनर्वसन योजनेसाठी कुटुंब म्हणजे काय?', N'झोपडपट्टी पुनर्वसन योजनेसाठी कुटुंब म्हणजे ज्यांची नावे दि. 01/01/2000 रोजीच्या मतदार यादीत एकाच झोपडीमध्ये राहत असल्याचे दर्शविण्यात आलेली आहेत, अशा त्या झोपडीत राहणाऱ्या व्यक्ती.', N'What is a family for a slum rehabilitation scheme?', N'For slum rehabilitation scheme, the family is the one whose name is The Electoral Roll dated 01/01/2000 shows the persons living in the same hut.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (10, N'एका पेक्षा जास्त कुटुंब एकाच झोपडीत प्रत्यक्ष राहत असली व त्यांचे कडे एकापेक्षा जास्त शिधापत्रिका असल्या तर त्या प्रत्येक कुटुंबास वेगळी सदनिका मिळेल का?', N'नाही, या योजनेत एका झोपडीत राहणाऱ्या सर्व व्यक्तींचे एकच कुटुंब म्हणून गणले जाते आणि त्यांना एकाच सदनिका मिळेल.', N'If more than one family actually lives in the same hut and they have more than one ration card, will each family get a separate flat?', N'No, in this scheme all persons living in a hut are treated as one family and they will get one flat.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (11, N'दिनांक 01/01/2000 रोजीच्या मतदार यादीत झोपडीधारकांचे नाव समाविष्ट आहे त्या कुटुंबातील प्रत्येकाला सदनिका मिळणार का?', N'नाही एकाच कुटुंबास एकच सदनिका मिळेल.', N'Will everyone in the family whose hut owner''s name is included in the voter list dated 01/01/2000 get a flat?', N'No single family will get a single flat.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (12, N'दिनांक 01/01/2000 रोजीच्या मतदार यादीत झोपडीधारकांचे नाव नाही परंतु सदर व्यक्ती त्या झोपडीमध्ये दि. 01/01/2000 पूर्वीपासून राहत असल्यास ती व्यक्ती योजनेत सहभागी होण्यास पात्र होईल का?', N'अशा प्रसंगी पात्रता सिद्ध करण्यासाठी सदर झोपडीधारकाची झोपडी व त्यामधील त्याचे वास्तव्य हे दि01/01/2000 रोजी किंवा त्यापूर्वीपासून असल्याचे शासकीय/ निमशासकीय संस्थांनी दिलेल्या दस्तऐवजाच्या आधारे सिद्ध करणे गरजेचे आहे. उदा. शासकीय, निमशासकीय किंवा स्थानिक स्वराज्य संस्थेचा परवाना (मुंबई दुकाने व संस्था अधिनियम 1948 अन्वये दिलेला परवाना, खानावळ/उपहार गृह परवाना, औद्योगिक परवाना, गुमास्ता परवाना इत्यादी.) सादर केला पाहिजे. झोपडीधारकाच्या नावाने व झोपडी असलेल्या पत्त्यावर दि 1 जानेवारी 2000 पूर्वीचे वीज बिल, दूरध्वनी देयक किंवा कर, व्यवसाय कर, आयकर इत्यादी करांचा भरणा केल्याचा पुरावा असला पाहिजे. वरीलपैकी कोणताही पुरावा सादर केल्यास झोपडीधारक योजनेत लाभ मिळण्यास पात्र होईल.', N'The name of the hut owner is not in the voter list dated 01/01/2000 but the person is in the hut on dated Will the person be eligible to participate in the scheme if he / she is already living before 01/01/2000?', N'In order to prove eligibility in such cases, it is necessary to prove that the hut owner''s hut and his residence in it is on or before 01/01/2000 on the basis of documents provided by government / semi-government organizations. E.g. Government, Semi-Government or Local Self Government Institution License (License issued under Mumbai Shops and Institutions Act, 1948, Canteen / Gift House License, Industrial License, Clerk License etc.) should be submitted. In the name of the hut owner and at the address of the hut dated 1 January 2000', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (13, N'केंद्र शासनाच्या मालकीच्या जमिनीवरील झोपडीधारकांना या योजनेचा लाभ मिळेल का?', N'केंद्र शासनाच्या मालकीच्या झोपडपट्टीबाधित जमिनीवर झोपडपट्टी पुनर्वसन योजना राबविण्यासाठी केंद्र शासनाने मंजुरी दिल्यास त्या जमिनीवर ही योजना राबविता येईल.', N'Will slum dwellers on Central Government owned land benefit from this scheme?', N'The scheme can be implemented on the land owned by the Central Government if the Central Government approves the implementation of the Slum Rehabilitation Scheme.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (14, N'झोपडपट्टी पुनर्वसन योजना राबविण्यासाठी कार्यपद्धती?', N'एखाद्या ठिकाणच्या झोपडपट्टीतील झोपडीधारकांनी एकत्र येऊन झोपडपट्टी पुनर्वसन योजना राबविण्याचा निर्णय घेतल्यास त्यांनी झोपडपट्टी पुनर्वसन प्राधिकरणाकडे नोंदणी केलेल्या व जमीन मालकांकडून जमीन विकसनाचे हक्क संपादित केलेल्या विकसकास किंवा अन्य विकसकास झोपुप्रा. राबविण्याबाबत विहित नमुन्यातील संमतीपत्र / करारपत्र नोटरी समोर निष्पादित करावे. झोपडपट्टीतील पात्र झोपडीधारकांपैकी किमान 70% झोपडीधारकांनी योजना राबविण्यासाठी विकसकास संमती दिल्यास विकासकाने दखल केलेला झोपडपट्टी पुनर्वसन योजनेचा प्रस्ताव मंजुरी साठी विचारात घेता येतो.', N'Procedures for implementing slum rehabilitation scheme?', N'If the slum dwellers of a place come together and decide to implement a slum rehabilitation scheme, they should go to the developer or other developer who has registered with the Slum Rehabilitation Authority and acquired the land development rights from the land owner. Consent letter / agreement in the prescribed form regarding implementation should be executed before a notary. If at least 70% of the eligible slum dwellers in the slums give their consent to the developer to implement the scheme, then the proposal of the slum rehabilitation scheme approved by the developer is approved.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (15, N'झोपडपट्टी पुनर्वसन योजनेस संमती न दिलेल्या झोपडीधारकांच्या कुटुंबास सदनिका/गळा मिळू शकतो काय?', N'झोपडीधारकांचे झोपडीतील वास्तव्य हे दि. 01/01/2000 पूर्वीपासूनचे असल्यास व अशा झोपडीधारकाचे नाव परिशिष्ट-2 मध्ये पात्र म्हणून समाविष्ट असल्यास त्या झोपडीधारकाने योजनेस संमती दिली नसेल तरीही त्यास योजनेमध्ये सदनिका/गळा मिळू शकतो.', N'Can a family of a slum dweller who has not given their consent to the slum rehabilitation scheme get a flat / neck?', N'The slum dwellers live in huts. If the hutholder is not eligible for the scheme even before 01/01/2000 and the name of such hut owner is included in Appendix-2 as eligible, he / she can get flat / neck in the scheme.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (16, N'झोपडपट्टी पुनर्वसन योजनेमध्ये पात्र असलेल्या झोपडीधारकाने पुनर्वसन योजनेतील सदनिका/गळा स्वीकारण्यास नकार दिल्यास त्या विरुद्ध कोणती कारवाई करण्यात येते?', N'असा झोपडीधारक त्याचा पुनर्वसनाचा हक्क गमावू शकतो आणि त्यास योजना क्षेत्रातून निष्कासित करण्यात येते.', N'What action is taken against a slum dweller who is eligible under the Slum Rehabilitation Scheme if he / she refuses to accept the flat / neck under the Rehabilitation Scheme?', N'Such a hut owner may lose his right of rehabilitation and be expelled from the scheme area.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (17, N'झोपडीधारकास एका पेक्षा जास्त विकसकास संमती देता येते काय?', N'नाही, एका झोपडीधारकास एकाच विकसकास संमती देता येते.', N'Can a hut owner consent to more than one developer?', N'No, a hut owner can consent to a single developer.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (18, N'झोपडीधारकांची पात्रता यादी (परिशिष्ट-2) म्हणजे काय?', N'परिशिष्ट-2 मध्ये योजना क्षेत्रातील सर्व झोपडीधारकांचे नावे तसेच योजनेचा लाभ मिळण्यास पात्र/अपात्र असलेले झोपडीधारक तसेच संबंधित झोपडीचे मोजमाप व वापराबाबतचा तपशील असतो.', N'What is the eligibility list of hutholders (Appendix-2)?', N'Appendix-2 contains the names of all the hut holders in the scheme area as well as the hut holders who are eligible / ineligible to avail the benefits of the scheme as well as the measurement and use of the respective huts.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (19, N'परिशिष्ट-2 चे महत्व काय?', N'परिशिष्ट-2 मध्ये पात्र म्हणून नाव समाविष्ट असल्याखेरीज झोपडपट्टीधारकास पुनर्वसन योजनेमध्ये मोफत सदनिका/गळा मिळू शकत नाही.', N'What is the significance of Appendix-2?', N'A slum dweller cannot get free flat / throat in the rehabilitation scheme unless the name is included as eligible in Appendix-2.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (20, N'झोपडीधारकांनी पात्रतेसंबंधीच्या पुराव्याचे कागदपत्र सक्षम प्राधिका-याकडे दखल न केल्यास होणारे परिणाम?', N'परिशिष्ट-2 साठी आवश्यक कागदपत्रे झोपडीधारकांनी सक्षम प्राधिकारी यांच्याकडे दखल करणे त्यांचे हिताचे आहे. अन्यथा असे झोपडीधारक अपात्र ठरल्याने पुनर्वसानाचा हक्क गमवू शकतात.', N'Consequences if the hut owner does not submit the proof of eligibility to the competent authority?', N'It is in the interest of the slum dwellers to submit the required documents for Appendix-2 to the competent authority. Otherwise, such hutholders may lose their right to rehabilitation due to ineligibility.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-08T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (21, N'परिशिष्ट-2 ची प्रत पाहणीसाठी कोठे उपलब्ध होईल?', N'सक्षम प्राधिकारी, परिशिष्ट-2 ची प्रत वसाहतीत ठळक ठिकाणी प्रसिद्ध करतात. तसेच ती झोपडपट्टी पुनर्वसन प्राधिकरणाचे कार्यालयात उपलब्ध होऊ शकते.', N'Where will a copy of Appendix-2 be available for inspection?', N'Competent authorities publish a copy of Appendix-2 in prominent places in the colony. It may also be available at the office of the Slum Rehabilitation Authority.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (22, N'परिशिष्ट-2 मधील पात्रतेबाबत काही शंका असल्यास त्याबाबत फेर तपासणी करता येते का?', N'होय. परिशिष्ट-2 प्रसिद्ध केल्यापासून 30 दिवसांचे आत झोपडीधारक हे मुख्य कार्यकारी अधिकारी, झोपडपट्टी पुनवर्सन प्रधिकारण यांचेकडे फेट तपासणीसाठी आर्ज करू शकतात.', N'If there is any doubt about the eligibility in Appendix-2, can it be re-examined?', N'Yes. Within 30 days of the publication of Appendix-2, slum dwellers can apply to the Chief Executive Officer, Slum Rehabilitation Authority for a fat inspection.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (23, N'एखाद्या झोपडीधारकाने खोटी कागदपत्रे तयार करून सदनिका मिळविली असल्यास त्याबाबत कोणाकडे तक्रार करावी.', N'ज्या व्यक्तीचे नाव संबंधित योजनेच्या परिशिष्ट-2 मध्ये अंतर्भूत आहे अशा पात्र झोपडीधारकाने त्याबाबत मुख्य कार्यकारी अधिकारी, झोपुप्रा यांचेकडे सविस्तर तपशिलासह तक्रार करावी.', N'If a hut owner has obtained a flat by producing false documents, who should he complain to?', N'The eligible hut owner whose name is included in Appendix-2 of the scheme concerned should report the matter in detail to the Chief Executive Officer, Zhopupra.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (24, N'सार्वजनिक हिताचे प्रकल्प बाधित जागेवर वसलेल्या झोपडपट्टीवासियांचे पुनर्वसन त्याच जागी करता येईल का?', N'सार्वजनिक हिताचे प्रकल्प राबविताना बाधित होणाऱ्या दि 1/1/2000 पूर्वीच्या झोपडीधारकांना पुनर्वसन सदनिका/ गळा मिळण्याचा हक्क आहे. तथापि त्यांचे पुनर्वसन त्याचा जागी करणे शक्य नसल्यास त्यांचे पुनर्वसन इतरत्र करण्यात येते. अशा पुनर्वसनासाठी झोपडीधारकांच्या संमतीची आवश्यकता नसते.', N'Is it possible to rehabilitate slum dwellers in the same place where public interest projects are affected?', N'Slum dwellers before 1/1/2000 who are obstructed in the implementation of public interest projects have the right to get rehabilitation flats. However, if their rehabilitation is not possible, they can be relocated elsewhere. Such rehabilitation does not require the consent of the hut owner.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (25, N'झोपडपट्टी पुनर्वसन योजनेचे कामकाज कोणते कायदे व नियमावलीनुसार करण्यात येते?', N'कायदे- १) महाराष्ट्र झोपडपट्टी (सुधारणा, निर्मुलन व पुनर्विकास) अधिनियम १९७१ २) महाराष्ट्र प्रादेशिक व नगररचना अधिनियम १९६६ नियमावली- १) नगरविकास विभागाने दि. ११/९/२०१४ रोजी मान्य केलेली विशेष नियमावली २) पात्रतेविषयक गृहनिर्माण विभागाने दि. १६/०५/२०१५ रोजीचे परिपत्रक ३) शासनातर्फे वेळोवेळी परिपत्रक देण्यात येणारे निर्देश', N'Slum Rehabilitation Scheme is governed by which laws and regulations?', N'Acts- 1) Maharashtra Slum (Improvement, Elimination and Redevelopment) Act 1971 2) Maharashtra Regional and Town Planning Act 1966 Rules- 1) Urban Development Department Special Rules approved on 11/9/2014 2) Eligibility Housing Department Circular dated 16/05/2015 3) Instructions issued from time to time by the Government', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (26, N'झोपडपट्टी पुनर्वसन योजनेचा प्रस्ताव झोपडीधारकांच्य सहकारी गृहनिर्माण संस्थेस दाखल करता येईल?', N'झोपुप्राचा प्रस्ताव झोपडीधारकाच्या गृहनिर्माण संस्थेस त्यांच्या सर्वसाधारण सभेची बहुमताने मंजुरी घेवून झोपुपप्राकडे नोंदणीकृत असलेल्या कोणत्याही विकासकाकडून दाखल करता येईल.', N'Can a proposal for a slum rehabilitation scheme be submitted to a co-operative housing society of slum dwellers?', N'The proposal of Zhopupra can be submitted to the housing organization of the slum owner by any developer registered with Zhopupra with the approval of the majority of their general meeting.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (27, N'झोपडपट्टी पुनर्वसन योजनेतील पात्र झोपडीधारकांना पुनर्वसन इमारतीतील सदनिकांचा ताबा कोणत्या पद्धतीने देण्यात येतो?', N'विकासक, पात्र झोपडीधारक तसेच झोपुप्रा प्रतिनिधी यांचे उपस्थितीत सोडत पद्धतीने पात्र झोपडीधारकांच्या सदनिकांचे वाटप निश्चित करणेत येते. यावेळी विधवा तसेच अपंग झोपडीधारकांना पहिले प्राधान्य देण्यात येते.', N'How is the possession of flats in rehabilitation building given to eligible slum dwellers under slum rehabilitation scheme?', N'The allotment of flats to eligible slum dwellers is decided in the presence of developers, eligible hut owners as well as Zhopupra representatives. Widows as well as disabled slum dwellers are given first priority at this time.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (28, N'झोपडीधारकांच्या सहकारी संस्थेस योजनेमध्ये कोणत्या इतर सेवासुविधा उपलब्ध करून देण्यात येतात?', N'झोपडीधारकांच्या गृहनिर्माण संस्थेस १२ चौ.मी. कार्पेट क्षेत्राचे सोसायटी ऑफीस तसेच ४ चौ.मी. कार्पेट क्षेत्राचे टॉयलेट देण्यात येते. तसेच योजनेतील पात्र झोपडीधारकांची कारपेट क्षेत्राची बालवाडी तसेच वेल्फेअर सेंटर सोसायटीस देण्यात येते.', N'What other services are provided in the scheme to the co-operative society of hut owners?', N'12 sq.m. Carpet area society office as well as 4 sq.m. Carpet area toilets are provided. The carpet area kindergarten as well as welfare center societies of eligible hut owners are also provided under the scheme.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (29, N'पुनर्वसन योजनेमध्ये खुली जागा ठेवण्यात येते किंवा कसे?', N'झोपडपट्टी पुनर्वसन योजनेचे क्षेत्र ४००० चौ.मी. पेक्षा जास्त असल्यास योजना क्षेत्राच्या ९०% विकसित करून झोपडीधारकांच्या गृहनिर्माण संस्थेस देण्यात येते.', N'Is open space included in the rehabilitation plan or how?', N'Area of ​​Slum Rehabilitation Scheme 4000 sq.m. If more than 90% of the plan area is developed and given to the slum housing society.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 1)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (30, N'झोपडपट्टी पुनर्वसन योजनेतील पुनर्वसन अनुज्ञेय घटकासाठी किती उंचीच्या इमारती अनुज्ञेय करण्यात येतात व त्याकरिता अग्निशामक व्यवस्था कशा पद्धतीने पुरविणेत येते?', N'झोपडपट्टी पुनर्वसन योजनेसाठी सर्वसाधारणपणे ४० मी. उंचीपर्यंतच्या इमारती अनुज्ञेय करण्यात येतात.पुनर्वसन घटकाचे काम पूर्ण होणेसाठी यापेक्षा जास्त उंची देखील अनुज्ञेय करणेचे अधिकार मुख्य कार्यकारी अधिकारी, झोपुप्रा यांना आहेत. या बहुमजली इमारतीसाठी मनपाचे मुख्य अग्निशामक अधिकारी यांचे ना-हरकत पत्रानुसार आवश्यक सुविधा पुरविणेत येतात.', N'How many tall buildings are allowed for the rehabilitation permit component of the Slum Rehabilitation Scheme and how the fire system is provided for it?', N'For slum rehabilitation scheme 40 m. Buildings up to height are allowed. The Chief Executive Officer, Zhopupra has the right to allow higher heights for the completion of the rehabilitation work. Necessary facilities are provided for this multi-storied building as per the no-objection letter of the Chief Fire Officer of the Corporation.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2021-07-09T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (31, N'झोपडपट्टी पुनर्वसन योजनेमध्ये समाविष्ट झाल्याने होणारे फायदे ?', N'1) योजनेमध्ये समाविष्ट झाल्याने स्वतःचे वैयक्तिक सर्व सोई-सुविधायुक्त हक्काचं व मोफत घर मिळेल. 2) प्रसन्न व आरोग्यदायी वातावरण मिळेल. 3) सर्व सोयींमुळे राहणीमान उंचावेल तसेच स्वच्छतेमुळे मुलाबाळांच्या आरोग्य चांगले राहील.', N'Benefits of being included in slum rehabilitation scheme?', N'1) Enrollment in the scheme will get one''s own personal all-facility right and free house. 2) Will get pleasant and healthy environment. 3) All amenities will raise the standard of living and cleanliness will improve the health of children.', N'A', 1, CAST(N'2023-06-08T00:00:00' AS SmallDateTime), NULL, NULL, NULL)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (32, N'झोपडपट्टी पुनर्वसन योजनेमध्ये समाविष्ट न झाल्याने होणारे तोटे ?', N'1) झोपडीधारकांना सर्व सोई-सुविधायुक्त हक्काचं व मोफत घर मिळणार नाही  2)अस्वच्छता गलिच्छ वस्तीत राहावे लागेल.  3)मुलाबाळांच्या आरोग्याच्या दृष्टीने धोकादायक 4)आवश्यक सेवेचा अभाव असल्याने गैरसोय
', N'Disadvantages of not being included in the slum rehabilitation scheme?', N'1) The slum dwellers will not get the right and free housing with all the comforts 2) They will have to live in unsanitary and dirty habitations. 3)Dangerous to children''s health 4)Inconvenience due to lack of essential services', N'A', 1, CAST(N'2023-06-08T00:00:00' AS SmallDateTime), NULL, NULL, NULL)
GO
INSERT [dbo].[faq] ([id], [faq], [answer], [faq_eng], [answer_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (33, N'अपात्र झोपडीधारकांसाठी झोपडपट्टी पुनर्वसन प्राधिकरणाची तरतूद ?', N'अपात्र झोपडीधारकाने रक्कम रुपये अडीच लाख SRA  कडे भरणा केल्यास त्यांना सदर योजनेमध्ये 300 चौ.फुट सदनिका मिळू शकेल', N'Provision of Slum Rehabilitation Authority for ineligible slum dwellers ?', N'The ineligible slum dwellers can get a 300 sq.ft flat under the scheme if they pay Rs.2.5 lakhs to the SRA.', N'A', 1, CAST(N'2023-06-20T00:00:00' AS SmallDateTime), 1, CAST(N'2023-06-20T00:00:00' AS SmallDateTime), 1)
GO
