INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (7, N'CEO Message', N'पुणे शहर हे महाराष्ट्राची सांस्कृतिक राजधानी म्हणून आणि पिंपरी-चिंचवड हे शहर उद्योग नगरी म्हणून ओळखले जाते. पुणे आणि पिंपरी-चिंचवड या शहरामध्ये उद्योग, व्यवसाय, शिक्षण तसेच रोजगार यासाठी देशाच्या अन्य भागातून मोठ्या प्रमाणात लोक स्थलांतरित होतात. शहरात नव्याने येणाऱ्या लोकांना त्यांच्या आर्थिक परिस्थितीचा विचार करता निवाऱ्याची सोय उपलब्ध होत नसल्याने  त्यांनी प्रदीर्घ काळापासून झोपडपट्टीमध्ये वास्तव्य केले आहे. 

पुणे शहरामध्ये 486 झोपडपट्ट्या असून त्यामध्ये जवळपास 1,65,000 एवढ्या कुटुंबाचे वास्तव्य असून शहराच्या एकूण लोकसंख्येच्या सुमारे 28 टक्के लोक झोपडपट्टीत राहत आहेत. पिंपरी-चिंचवड महानगरपालिका क्षेत्रात 71 झोपडपट्ट्या असून त्यामध्ये सुमारे 35,261 कुटुंबाचे वास्तव्य आहे. शहराच्या उकूण लोकसंख्येच्या सुमारे 14.78 टक्के लोक झोपडपट्टीत राहत आहेत.झोपडपट्टीतील अस्वच्छ व अनारोग्य  असलेल्या परिस्थितीत तेथील लोक खडतर अवस्थेत जीवन कंठीत असतात. झोपडपट्टीत राहणाऱ्या आर्थिकदृष्ट्या दुर्बल असलेल्या  पात्र कुटुंबाना त्यांच्या स्वप्नातील पक्के घर राज्य शासनाने प्राधिकरणाच्या मध्यामातुने विनामुल्य देऊ केले आहे. शासनाने झोपडपट्टीने व्यापलेल्या जमिनीचा साधनसंपत्ती म्हणून सुयोग्य वापर करून प्रोत्साहनात्मक चटईक्षेत्र निर्देशांक अनुज्ञेय करून झोपडपट्टी पुनर्वसन योजना अंमलात आणली आहे. 

झोपडपट्टी पुनर्वसन योजने अंतर्गत पात्र झोपडपट्टीवासियांना आवश्यक सोयी सुविधायुक्त घर विनामुल्य मालकी हक्काने उपलब्ध करून झोपडपट्टीवासी यांचे राहणीमान व जीवनमान उंचावण्याचे राज्य शासनाचे ध्येय आहे. त्यानुसार योजनेचा लाभ घेवून पुणे व पिंपरी-चिंचवड ही शहरे झोपडपट्टी मुक्त करणे हा प्राधिकरणाचा ध्यास आहे “अल्पायुषी प्राधिकरण आणि पुनर्विकास चिरंतर” झोपडपट्टी पुनर्वसन योजनेचे ध्येय आहे. 
', N'The city of Pune is known as the cultural capital of Maharashtra and the city of Pimpri-Chinchwad as the industrial city. The cities of Pune and Pimpri-Chinchwad attract a large number of people from other parts of the country for industry, business, education and employment. The new arrivals in the city have been living in slums for a long time as they do not have access to shelter considering their economic situation.

There are 486 slums in Pune city where about 1,65,000 families live and about 28 percent of the total population of the city lives in slums. There are 71 slums in the Pimpri-Chinchwad Municipal Corporation area with around 35,261 families living in them. About 14.78 percent of the total population of the city is living in slums. The people of the slums are living in a difficult condition due to unsanitary and unsanitary conditions.

The economically weaker deserving families living in slums have been offered their dream concrete house free of charge by the state government through the authority.

The government has implemented a slum rehabilitation scheme by sanctioning an incentive mat area index for proper utilization of slum occupied land as a resource. Under the slum rehabilitation scheme, the state government aims to raise the standard of living and standard of living of the slum dwellers by providing free ownership rights to eligible slum dwellers.

Accordingly, it is the intention of the authority to free the cities of Pune and Pimpri-Chinchwad from slums by taking advantage of the scheme. 

', N'A', 1, CAST(N'2021-01-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-16T00:00:00' AS SmallDateTime), 7)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (9, N'CEO Name', N' श्री. सतीशकुमार कमल दत्तात्रय खडके', N' Shri. Satishkumar Kamal Dattatray Khadke', N'A', 1, CAST(N'2021-01-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-09-12T00:00:00' AS SmallDateTime), 5)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (10, N'about_line1', N'पुणे शहर हे महाराष्ट्राची सांस्कृतिक राजधानी म्हणून आणि पिंपरी-चिंचवड हे शहर उद्योग नगरी म्हणून ओळखले जाते. पुणे आणि पिंपरी-चिंचवड या शहरामध्ये उद्योग, व्यवसाय, शिक्षण तसेच रोजगार यासाठी देशाच्या अन्य भागातून मोठ्या प्रमाणात लोक स्थलांतरित होतात. स्थलांतरित होणाऱ्या लोकांना किफायतशीर दरातील निवाऱ्याची सोय उपलब्ध होत नसल्याने, झोपडपट्टीमध्ये वास्तव्य करणे भाग पडते. सद्यस्थितीत पुणे शहरामध्ये ४८६ झोपडपट्ट्यामध्ये साधारण १,६५,००० एवढ्या कुटुंबाचे वास्तव्य असून शहराच्या एकूण लोकसंख्येच्या सुमारे २८ टक्के लोक झोपडपट्टीत राहत आहेत. पिंपरी-चिंचवड महानगरपालिका क्षेत्रात ७१ झोपडपट्ट्या असून त्यामध्ये सुमारे ३५,२६१ कुटुंबाचे वास्तव्य आहे. शहराच्या एकूण लोकसंख्येच्या सुमारे १४.७८ टक्के लोक झोपडपट्टीत राहत आहेत. झोपडपट्टीतील अस्वच्छ व अनारोग्य असलेल्या परिस्थितीत तेथील लोक खडतर अवस्थेत जीवन कंठीत असतात. सर्वसामान्य जनतेप्रमाणे झोपडीधारकाचे स्वत:च्या घराचे स्वप्न असते. या स्वप्नपूर्तीसाठी महाराष्ट्र शासन कटिबद्ध आहे. ', N'Pune City is known as the cultural capital of Maharashtra, and Pimpri-Chinchwad is recognized as an industrial city. Both Pune and Pimpri-Chinchwad attract a large number of people from other parts of the country due to industries, businesses, education, and employment opportunities. However, due to the lack of affordable housing for these migrants, they are compelled to live in slums.

Currently, in Pune city, approximately 165,000 families reside in 486 slum clusters, making up about 28% of the city''s total population. In the Pimpri-Chinchwad Municipal Corporation area, there are 71 slum clusters, home to around 35,261 families. About 14.78% of the total population of the city resides in slums.

The residents of these slums live in unhygienic and unhealthy conditions, enduring difficult and challenging lives. Like the general population, slum dwellers also dream of owning their own homes. The Maharashtra government is committed to fulfilling this dream.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (11, N'about_line2', N'महाराष्ट्र शासनाच्या महत्वाकांक्षी धोरणानुसार, झोपडपट्टीधारकांना आवश्यक त्या सोयी सुविधायुक्त मोफत घर/सदनिका उपलब्ध करून देऊन त्यांचे राहणीमान व जीवनमान उंचावणे यासाठीचे एक प्रभावी अभियान म्हणजे महाराष्ट्र शासनाची झोपडपट्टी पुनर्वसन योजना होय. या योजनेमध्ये शासनाने झोपडपट्टीने व्यापलेल्या जमिनीचा साधनसंपत्ती म्हणून सुयोग्य वापर करून प्रोत्साहनात्मक चटईक्षेत्र निर्देशांक अनुज्ञेय करून झोपडपट्टी पुनर्वसन योजना राबविली जाते. त्यासाठी शासनाने झोपडपट्टी पुनर्वसन प्राधिकरणाची स्थापना केली आहे. ', N'As per the ambitious policy of the Maharashtra government, an effective initiative to improve the living standards and quality of life of slum dwellers by providing them with essential amenities and free housing/apartments is the Maharashtra Slum Rehabilitation Scheme. Under this scheme, the government makes optimal use of the land occupied by slums as a resource and implements the slum rehabilitation plan by encouraging the allocation of appropriate land use. For this purpose, the government has established the Slum Rehabilitation Authority.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (12, N'about_line3', N'१. पुणे व पिंपरी-चिंचवड महानगरपालिका क्षेत्रातील झोपडपट्टी क्षेत्र तसेच, पुणे व पिंपरी-चिंचवड महानगरपालिकेमध्ये नव्याने समावेश झालेली गावामधील झोपडपट्टी क्षेत्र.', N'1. Slum areas within the Pune and Pimpri-Chinchwad Municipal Corporation limits, as well as newly included slum areas from villages within Pune and Pimpri-Chinchwad Municipal Corporations.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (13, N'about_line4', N'२. पुणे व पिंपरी चिंचवड महानगरपालिका क्षेत्रातील पिंपरी चिंचवड नवनगरविकास प्राधिकरण तसेच महाराष्ट्र औद्योगिक विकास महामंडळांतर्गत येणाऱ्या झोपडपट्टी क्षेत्र', N'2. Slum areas within the Pune and Pimpri-Chinchwad Municipal Corporation limits, as well as slum areas under the Pimpri-Chinchwad New Township Development Authority and Maharashtra Industrial Development Corporation.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
