INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (16, N'about_line7', N'३. झोपडपट्टी पुनर्वसन योजनेअंतर्गंत पात्र झोपडीधारकांना स्वत:च्या मालकीचे सर्व सुविधायुक्त 300 चौ.फूट चटई क्षेत्राची सदनिका विनामूल्य उपलब्ध करून देणे.', N'3. To provide eligible slum dwellers with their own fully equipped 300 square feet carpet area tenements free of cost under the Slum Rehabilitation Scheme.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
