INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (17, N'about_line8', N'१. महाराष्ट्र झोपडपट्टी (सुधारणा, निर्मूलन व पुनर्विकास) अधिनियम, १९७१ च्या कलम ३(अ) नुसार स्थापना.', N'1. Maharashtra Slum ( Improvement Establishment as per Section 3 (a) of the Abolition and Redevelopment Act, 1971.', N'A', 1, CAST(N'2021-03-01T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
