INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (25, N'about_line2_1', N'शासनाने प्राधिकरणाच्या माध्यमातून पात्र झोपडीधारकांना त्यांच्या स्वप्नातील मालकी हक्काचे घर विनामूल्य देवू केले आहे. तसेच दि. १६ मे, २०१८ रोजीच्या शासन निर्णयानुसार, असंरक्षित झोपडीधारकांसाठी सशुल्क योजनेच्या माध्यमातून झोपडीधारकांच्या स्वप्नाला बळकटी प्राप्त होत आहे. झोपडपट्टी मुक्त शहर करणे हा प्राधिकरणाचा ध्यास आहे. “अल्पायुषी प्राधिकरण आणि पुनर्विकास चिरंतर” झोपडपट्टी पुनर्वसन योजनेचे ध्येय आहे.', N'As per the ambitious policy of the Maharashtra government, an effective initiative to improve the living standards and quality of life of slum dwellers by providing them with essential amenities and free housing/apartments is the Maharashtra Slum Rehabilitation Scheme. Under this scheme, the government makes optimal use of the land occupied by slums as a resource and implements the slum rehabilitation plan by encouraging the allocation of appropriate land use. For this purpose, the government has established the Slum Rehabilitation Authority.', N'A', 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
INSERT [dbo].[mst_content_single] ([id], [content_type], [description], [description_eng], [active_status], [created_by], [created_date], [updated_by], [updated_date], [updated_count]) VALUES (26, N'about_line_sthapana', N'झोपडपट्टी पुनर्वसन प्राधिकरण, पुणे व पिंपरी-चिंचवड या प्राधिकरणाची स्थापना महाराष्ट्र शासन, गृहनिर्माण विभागाकडील दिनांक ३० जून २००५ रोजीच्या अधिसूचनेन्वये करण्यात आली आहे. ', N'The establishment of the Slum Rehabilitation Authority, Pune and Pimpri-Chinchwad was made by the Maharashtra Government, Housing Department, through a notification dated June 30, 2005.', N'A', 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 1, CAST(N'2025-01-18T00:00:00' AS SmallDateTime), 2)
GO
